cat > ledger/importer.py <<'EOF'
"""Импорт банковских выписок.

Поддерживаются форматы (нужные колонки ищутся по названию без учёта регистра
и краевых пробелов, в любом порядке; лишние колонки не читаются):

    nova         date,amount,description               (разделитель ",")
    sfera        Дата;Сумма;Описание                   (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход           (разделитель ";")

Пример «Новы»:

    date,amount,description
    2026-03-01,-350.00,Кофейня Зерно
"""

from __future__ import annotations

import csv
import dataclasses
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field
from decimal import Decimal

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementError, StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

# формат -> (разделитель, обязательные колонки в нижнем регистре)
_FORMATS: dict[str, tuple[str, tuple[str, ...]]] = {
    "nova": (",", NOVA_COLUMNS),
    "sfera": (";", ("дата", "сумма", "описание")),
    "sfera_split": (";", ("дата", "описание", "приход", "расход")),
}

_SFERA_DATE = re.compile(r"^\d{2}\.\d{2}\.\d{4}$")
_SFERA_AMOUNT = re.compile(r"^[+-]?(\d{1,3}([  ]\d{3})+|\d+)(,\d{1,2})?$")
_JUNK_CHARS = re.compile(r"[\s;,]")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)


def normalize_description(text: str) -> str:
    """Нормализация описания для сравнения (то же, что rules.normalize_text)."""
    return normalize_text(text)


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("cannot decode file as utf-8 or cp1251") from exc


def _header_line_no(text: str) -> int | None:
    first = text.splitlines()[0] if text else ""
    return 1 if first.strip() else None


def _header_columns(text: str, fmt: str) -> dict[str, int] | None:
    """Индексы нужных колонок заголовка для формата fmt или None, если не подходит."""
    delimiter, required = _FORMATS[fmt]
    try:
        cells = next(csv.reader(io.StringIO(text, newline=""), delimiter=delimiter), None)
    except csv.Error:
        return None
    if not cells:
        return None
    found: dict[str, int] = {}
    for idx, cell in enumerate(cells):
        found.setdefault(cell.strip().casefold(), idx)
    if any(name not in found for name in required):
        return None
    return {name: found[name] for name in required}


def _resolve_format(text: str, fmt: str | None) -> tuple[str, dict[str, int]]:
    line_no = _header_line_no(text)
    if fmt is not None:
        if fmt not in _FORMATS:
            raise UnknownFormatError(f"unknown format {fmt!r}")
        columns = _header_columns(text, fmt)
        if columns is None:
            raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=line_no)
        return fmt, columns
    matches = [(name, cols) for name in _FORMATS if (cols := _header_columns(text, name))]
    if len(matches) != 1:
        reason = "ambiguous statement header" if matches else "unrecognized statement header"
        raise UnknownFormatError(reason, line_no=line_no)
    return matches[0]


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку; при неудаче — UnknownFormatError."""
    text, _ = _read_text(path)
    return _resolve_format(text, None)[0]


def _is_junk(cells: list[str]) -> bool:
    return not _JUNK_CHARS.sub("", "".join(cells))


def _sfera_amount(text: str, *, signed: bool) -> Decimal:
    cleaned = text.strip()
    if not _SFERA_AMOUNT.match(cleaned) or (not signed and cleaned[0] in "+-"):
        raise ValidationError(f"invalid amount: {text!r}")
    sign = ""
    if cleaned[0] in "+-":
        sign, cleaned = cleaned[0], cleaned[1:]
    digits = cleaned.replace(" ", "").replace(" ", "").replace(",", ".")
    return parse_amount(sign + digits)


def _field(cells: list[str], columns: dict[str, int], name: str) -> str:
